/**
 * Curated demo snapshots — generated by scripts/snapshot-repo.ts from public/demo/<file>.json.
 * Numbers here are hardcoded (not fetched) so the example cards render their "N vendors -> M
 * substrates" summary with zero network calls; clicking a card fetches the actual snapshot JSON.
 *
 * Regenerate with: tsx scripts/rank-candidates.ts (to pick repos), then
 * tsx scripts/snapshot-repo.ts <owner/repo> for each — then update this file by hand from its
 * printed summary line.
 */
export interface ExampleRepo {
  owner: string
  repo: string
  /** Path under public/ — fetched relative to the site root. */
  file: string
  vendors: number
  substrates: number
  sha: string
  branch: string
  /** ISO timestamp from the snapshot's generatedAt field. */
  snapshotDate: string
  blurb: string
}

